import type { GameState } from '../engine';
import type { DraftModel } from './draft';
// Generated by scripts/train-draft-general.ts: one model for every map and mode (see below).
import general from './models/general.json';
// Generated by scripts/train-draft.ts (the older approach, used only while general.json is untrained):
// one model per map and game mode. `<map>.json` is the default (legendaries, no trainers); `-nl`
// without legendaries, `-t` with trainers, `-nlt` both. Do not edit the JSON by hand.
import meadow from './models/meadow.json';
import meadowNl from './models/meadow-nl.json';
import meadowNlt from './models/meadow-nlt.json';
import meadowT from './models/meadow-t.json';
import river from './models/river.json';
import riverNl from './models/river-nl.json';
import riverNlt from './models/river-nlt.json';
import riverT from './models/river-t.json';

export const DRAFT_MODELS: Record<string, DraftModel> = {
  meadow, 'meadow-nl': meadowNl, 'meadow-t': meadowT, 'meadow-nlt': meadowNlt,
  river, 'river-nl': riverNl, 'river-t': riverT, 'river-nlt': riverNlt,
};

/** The model key for a game mode: '' (legendaries, no trainers), 'nl', 't' or 'nlt'. */
export function modeSuffix(legendaries: boolean, trainers: boolean): string {
  return `${legendaries ? '' : 'nl'}${trainers ? 't' : ''}`;
}

/** The mode of a match in progress. */
export const modeOf = (s: GameState): string => modeSuffix(s.draft.legendPool.length > 0, !!s.trainers);

interface CardValues {
  A: Record<string, number>;
  D: Record<string, number>;
}
interface Correction extends CardValues {
  bias: number;
}

/**
 * One draft model for every context: shared card values plus corrections for the map, for playing
 * without legendaries and for trainer mode (scripts/train-draft-general.ts). The corrections that apply
 * are added up into a DraftModel, so a map or mode it has never seen still gets the shared values.
 */
export interface GeneralDraftModel extends CardValues {
  games: number;
  lambda: number;
  lambdaDelta: number;
  /** The contexts it was trained on (`<map>[-<mode>]`). */
  contexts: string[];
  bias: number;
  matchup: number;
  priorA: number;
  priorD: number;
  maps: Record<string, Correction>;
  noLegends: Correction;
  withTrainers: Correction;
  trainers: Record<string, { A: number; D: number; synA: number; synD: number }>;
}

export const GENERAL_MODEL: GeneralDraftModel = general;

/** The general model's DraftModel for one map and mode. */
export function composeDraftModel(g: GeneralDraftModel, mapId: string, legendaries: boolean, trainers: boolean): DraftModel {
  const parts = [g.maps[mapId], legendaries ? undefined : g.noLegends, trainers ? g.withTrainers : undefined].filter((c): c is Correction => !!c);
  const side = (k: 'A' | 'D') => Object.fromEntries(Object.entries(g[k]).map(([id, v]) => [id, parts.reduce((a, c) => a + (c[k][id] ?? 0), v)]));
  return {
    games: g.games,
    lambda: g.lambda,
    bias: parts.reduce((a, c) => a + c.bias, g.bias),
    matchup: g.matchup,
    priorA: g.priorA,
    priorD: g.priorD,
    A: side('A'),
    D: side('D'),
    ...(trainers ? { trainers: g.trainers } : {}),
  };
}

const composed = new Map<string, DraftModel>();

/**
 * The draft model for `mapId` in the given mode: the general model's, once it is trained; until then
 * the per-mode model, falling back to the map's default model, then to the first map's.
 */
export function draftModelFor(mapId: string, mode = ''): DraftModel {
  if (GENERAL_MODEL.games > 0) {
    const key = `${mapId}|${mode}`;
    let m = composed.get(key);
    if (!m) {
      m = composeDraftModel(GENERAL_MODEL, mapId, !mode.includes('nl'), mode.includes('t'));
      composed.set(key, m);
    }
    return m;
  }
  const exact = mode ? DRAFT_MODELS[`${mapId}-${mode}`] : undefined;
  if (exact && exact.games > 0) return exact;
  const m = DRAFT_MODELS[mapId];
  return m && m.games > 0 ? m : DRAFT_MODELS.meadow;
}
